RbI51S.css:
.phw-c-e6588c8f {
    box-shadow: var(--box-shadow-style-1);
}
.phw-c-e6588c8f-header-nav-block,.phw-c-e6588c8f-nav-mobile-block {
    flex: 1;
}
.phw-c-e6588c8f-header-logo {
    max-width: 118px;
}
.phw-c-e6588c8f-logo-block {
    width: 240px;
}

/* We have to enable this later after functionality is done so keeping it commented.
.phw-c-e6588c8f-addition-widgets-block > ul > li + li{
    border-inline-start: 1px solid var(--stroke-dark);
} */

@media (max-width: 1199.98px){
    .phw-c-e6588c8f-logo-md-block{
        flex:1;
    }
    .phw-c-e6588c8f-nav-mobile-block {
        flex-grow: unset;
    }
    .phw-c-e6588c8f-nav-mobile-block.phw-mobile-menu-active {
        display: block;
    }
    .phw-c-e6588c8f-header-logo {
        max-height: 40px;
        max-width: 98px;
    }
}
@media (max-width: 767.98px) {
    .phw-c-e6588c8f-logo-block{
        width: 100%;
    }
    .nav-mobile-block {
        padding-bottom: 110px;
    }
    .phw-s-custom-button-mobile {
        position: fixed;
        bottom: 0;
        z-index: 98;
        width: 100%;
        padding: 20px;
        text-align: center;
        display: none;
        left: 0;
        right: 0;
        background: var(--white);
    }
    .phw-c-e6588c8f-logo-md-block {
        flex: 1;
    }
    header nav.phw-menu-expanded ul.phw-menu-list {
        display: block;
    }
    header ul .nav-item button,
    header ul .nav-item a {
        padding: calc(var(--pu-space) * 1.5);
        display: block;
    }
    .phw-c-e6588c8f-candidate-login {
        display: none;
    }
    .phw-c-e6588c8f-header-logo {
        max-height: 32px;
        max-width: 80px;
    }
}
@media (max-width: 575.98px) {
    .phw-c-e6588c8f-logo-block {
        padding-inline-start: 0px;
    }
}

CLAr5U.css:
/* .phw-c-532351e5-top-section {
    border-top: 1px solid var(--stroke-dark);
} */
.phw-c-532351e5-border-left {
    border-inline-start: 1px solid var(--stroke-dark);
}
[data-component='personal-information'][class*='phw-d-'][class*='-none'] + .phw-c-532351e5-border-left {
    border-inline-start: none;
}
.phw-c-532351e5-middle-section {
    border-top: 1px solid var(--stroke-dark);
    border-bottom: 1px solid var(--stroke-dark);
}
.phw-c-532351e5-description-section a {
    word-break: break-word;
}
.phw-c-532351e5-bottom-section ul li:first-child {
    padding-inline-start: 0;
}
.phw-c-532351e5-row-gap {
    row-gap: calc(var(--mu-space) * 2);
}
@media screen and (max-width: 767.98px) {
    .phw-c-532351e5-border-left {
        border-inline-start: 0;
        border-top: 1px solid var(--stroke-dark);
    }
    [data-component='personal-information'][class*='phw-d-'][class*='-none'] + .phw-c-532351e5-border-left {
        border-top: none;
    }
}
